      { c: ['أولاً: الحساب والواجهة، لتعرف أين كل شيء.', 'First: your account and the interface, so you know where everything is.'], lit: 1, hl: 'stop0' },
      { c: ['ثم تبني خطة مشروع كاملة وتراها بطرق عرض مختلفة.', 'Then you build a full project plan and see it in different views.'], lit: 3, hl: 'stop2' },
      { c: ['بعدها الذكاء الاصطناعي والوكلاء، والتواصل مع الفريق ولوحات المعلومات.', 'Next come AI and agents, team communication and dashboards.'], lit: 6, hl: 'stop5' },
      { c: ['وأخيراً القوالب والإعدادات والأتمتة… لتعمل كالمحترفين.', 'Finally templates, settings and automations… so you work like a pro.'], lit: 11, hl: 'stop10', hello: ['كل موضوع: افهم ← شاهد ← جرّب ← اختبر نفسك.', 'Every topic: understand → watch → try → check yourself.'] }
