    quiz: { q: ['أين تعيش المهام في ClickUp؟', 'Where do tasks live in ClickUp?'], o: [['داخل المجلد مباشرة', 'Directly inside a Folder'], ['داخل القائمة', 'Inside a List'], ['داخل مساحة العمل', 'Inside the Workspace']], a: 1, why: ['المهام توضع دائماً داخل قائمة؛ المجلد يجمع القوائم فقط.', 'Tasks always sit inside a List; a Folder only groups Lists.'] }
