    ex: ['في نهاية الربع أغلقت مديرة المشروع 40 مهمة مكتملة بالتحديد الجماعي في دقيقة واحدة بدلاً من ساعة.', 'At quarter end the project manager closed 40 finished tasks with a bulk selection in one minute instead of an hour.'],
    wrong: ['حذف جماعي سريع دون مراجعة التحديد.', 'A quick bulk delete without checking the selection.'],
    right: ['راجع عدد المهام المحددة قبل أي إجراء، خاصة الحذف.', 'Check how many tasks are selected before any action, especially delete.'],
    quiz: { q: ['متى تفيدك الإجراءات الجماعية؟', 'When do bulk actions help you?'], o: [['عند تغيير مهمة واحدة', 'When changing a single task'], ['عند تطبيق نفس التغيير على عدة مهام', 'When applying the same change to several tasks'], ['عند كتابة تعليق', 'When writing a comment']], a: 1, why: ['التحديد الجماعي يوفر تكرار نفس الخطوة لكل مهمة.', 'Bulk selection saves repeating the same step for every task.'] }
