      { c: ['اختر المنطقة لكل مهمة من القائمة المنسدلة.', 'Pick each task’s region from the dropdown.'], cols: ['assignee', 'due', 'region'], rows: C4_FIB(), hl: 't3-region', click: true },
      { c: ['الآن يمكنك التصفية حسب المنطقة: «صلالة» فقط.', 'Now you can filter by region: “Salalah” only.'], rows: C4_FIB().filter(r => r.k !== 't3'), filter: ['المنطقة: صلالة', 'Region: Salalah'], hl: 'flt' }
