function TREE_C4() { return [{ k: 'sp-ops', l: 0, t: 'space', n: ['العمليات', 'Operations'] }, { k: 'fd-fib', l: 1, t: 'folder', n: ['إطلاق الألياف - صلالة', 'Fibre launch - Salalah'] }, { k: 'ls-plan', l: 2, t: 'list', n: ['التخطيط', 'Planning'] }, { k: 'ls-del', l: 2, t: 'list', n: ['التنفيذ', 'Delivery'] }]; }
function C4_KH(sel, w) { return [C4R('k1', ['طلب تصاريح البلدية', 'Request municipality permits'], { who: w, due: C4D(18), prio: 'normal', sel }), C4R('k2', ['متابعة المقاول', 'Follow up the contractor'], { who: w, due: C4D(19), prio: 'high', sel }), C4R('k3', ['تحديث المخطط', 'Update the drawing'], { who: w, due: C4D(21), prio: 'low', sel }), C4R('k4', ['مسح المواقع', 'Survey sites'], { who: 'salim', due: C4D(12), st: 'done' })]; }
